SELECT * FROM ( SELECT DISTINCT pl.*, ui.nickname AS writer_name, (SELECT COUNT(*) FROM chatroom WHERE pot_listing_id = pl.id) AS chatroom_count, (SELECT COUNT(*) FROM pot_listing_bookmark WHERE pot_listing_id = pl.id) AS bookmark_count FROM pot_listing pl JOIN user_info ui on ui.uuid = pl.writer_uid LEFT JOIN pot_listing_tag_mapping ptm ON ptm.pot_listing_id = pl.id LEFT JOIN plant_tag pt ON pt.id = ptm.plant_tag_id WHERE 1=1
AND pl.id < #{cursorId}
AND (pl.title LIKE '%' || #{keyword} || '%' OR pl.description LIKE '%' || #{keyword} || '%')
AND pt.id IN
#{tagId}
ORDER BY pl.id DESC ) WHERE ROWNUM <= #{size}
